SELECT id, dept_id, manager_id, job_title, hire_date, level, AVG(salary) OVER (PARTITION BY level ORDER BY salary, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS salary_avg_3_prior, DENSE_RANK() OVER w_ordered AS salary_dense_rank, LEAD(salary, 2) OVER (PARTITION BY job_title ORDER BY salary, id) AS next_salary, NTILE(10) OVER (PARTITION BY level, job_title ORDER BY salary DESC, id) AS salary_bucket, FIRST_VALUE(level) IGNORE NULLS OVER (PARTITION BY job_title, manager_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_level FROM employees WHERE full_name LIKE '%Sris%' WINDOW w_ordered AS (PARTITION BY dept_id ORDER BY salary DESC);
